package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsNone_TriageGen2Test {

    @Test
    public void testContainsNone_NullInputs() {
        // If cs is null, return true
        assertTrue(StringUtils.containsNone(null, new char[]{'a'}));
        // If searchChars is null, return true
        assertTrue(StringUtils.containsNone("abc", null));
        // If both are null, return true
        assertTrue(StringUtils.containsNone(null, null));
    }

    @Test
    public void testContainsNone_EmptyInputs() {
        // Empty cs, should return true (contains no characters from searchChars)
        assertTrue(StringUtils.containsNone("", new char[]{'a', 'b'}));
        // Empty searchChars, should return true (no characters can be found)
        assertTrue(StringUtils.containsNone("abc", new char[]{}));
    }

    @Test
    public void testContainsNone_BasicBMP() {
        // No match
        assertTrue(StringUtils.containsNone("abc", new char[]{'d', 'e'}));
        // Match found (BMP)
        assertFalse(StringUtils.containsNone("abc", new char[]{'b', 'z'}));
        // Match found (multiple)
        assertFalse(StringUtils.containsNone("apple", new char[]{'p'}));
    }

    @Test
    public void testContainsNone_Surrogates() {
        // High surrogate character: U+1F600 (Grinning Face 😀) 
        // In Java, this is represented by two chars: \uD83D and \uDE00
        char highSurrogate = '\uD83D';
        char lowSurrogate = '\uDE00';
        String emoji = "\uD83D\uDE00";

        // Case 1: Full surrogate pair matches
        char[] searchPair = {highSurrogate, lowSurrogate};
        assertFalse("Should return false when full surrogate pair matches", 
            StringUtils.containsNone(emoji, searchPair));

        // Case 2: Only high surrogate in searchChars matches, but it's the last element in searchChars
        // The code logic: if (j == searchLast) return false;
        char[] searchLastOnlyHigh = {highSurrogate};
        assertFalse("Should return false if high surrogate is the last char in search array (mimics String.indexOf behavior)", 
            StringUtils.containsNone(emoji, searchLastOnlyHigh));

        // Case 3: High surrogate matches, but subsequent char in searchChars does NOT match low surrogate
        char[] searchMismatchLow = {highSurrogate, '\uFFFF'};
        assertTrue("Should return true if high surrogate matches but next char in searchChars doesn't match the low surrogate in cs", 
            StringUtils.containsNone(emoji, searchMismatchLow));

        // Case 4: High surrogate matches, and next char in searchChars matches, but it's not at the end of searchChars
        // This tests the branch: if (i < csLast && searchChars[j + 1] == cs.charAt(i + 1))
        char[] searchPartialMatch = {highSurrogate, lowSurrogate, 'x'};
        assertFalse("Should return false if high surrogate and its low surrogate match", 
            StringUtils.containsNone(emoji, searchPartialMatch));

        // Case 5: High surrogate in cs, but searchChars contains only a different character at that index
        assertTrue(StringUtils.containsNone(emoji, new char[]{'z'}));
    }

    @Test
    public void testContainsNone_EdgeCases() {
        // Single character match
        assertFalse(StringUtils.containsNone("a", new char[]{'a'}));
        // Single character no match
        assertTrue(StringUtils.containsNone("a", new char[]{'b'}));
        // Search chars longer than cs
        assertFalse(StringUtils.containsNone("a", new char[]{'a', 'b', 'c'}));
        // Search chars shorter than cs
        assertFalse(StringUtils.containsNone("abc", new char[]{'b'}));
    }
}
